    public static ArrayList<Long> removeDuplicates(ArrayList<Long> numbers) {
        Map<Long, Integer> countMap = new HashMap<>();

        // Count occurrences of each number
        for (Long number : numbers) {
            countMap.put(number, countMap.getOrDefault(number, 0) + 1);
        }

        // Create a new list to store unique numbers
        ArrayList<Long> uniqueNumbers = new ArrayList<>();

        // Add numbers to the new list only if they occur once
        for (Long number : numbers) {
            if (countMap.get(number) == 1) {
                uniqueNumbers.add(number);
            }
        }

        return uniqueNumbers;
    }

}

