    // >>> strangeSortList((new ArrayList<Long>(Arrays.asList())))
    // (new ArrayList<Long>(Arrays.asList()))
    public static ArrayList<Long> strangeSortList(ArrayList<Long> lst) {
        ArrayList<Long> result = new ArrayList<>();
        while (!lst.isEmpty()) {
            // Add the minimum value
            long min = Collections.min(lst);
            result.add(min);
            lst.remove(new Long(min));

            // If there are still elements left, add the maximum value
            if (!lst.isEmpty()) {
                long max = Collections.max(lst);
                result.add(max);
                lst.remove(new Long(max));
            }
        }
        return result;
    }

}

